from itertools import combinations
import random

def check_graph(edges, n=8):
    """Check if a graph satisfies all constraints."""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check minimum degree >= 3
    for i in range(n):
        if len(adj[i]) < 3:
            return False, "min degree < 3"

    # Check maximum degree <= 4
    for i in range(n):
        if len(adj[i]) > 4:
            return False, "max degree > 4"

    # Check number of edges between 13 and 16
    if len(edges) < 13 or len(edges) > 16:
        return False, f"edges = {len(edges)}"

    # Check chromatic number <= 3 (3-colorable)
    if not is_k_colorable(adj, n, 3):
        return False, "not 3-colorable"

    # Check chromatic number >= 2 (has at least one edge)
    if len(edges) == 0:
        return False, "no edges"

    return True, "valid"

def is_k_colorable(adj, n, k):
    """Check if graph is k-colorable using backtracking."""
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

