def verify_solution(edges, n=8):
    """Thoroughly verify the solution."""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    print("Adjacency list:")
    for i in range(n):
        print(f"  Vertex {i}: {sorted(adj[i])} (degree {len(adj[i])})")

    degrees = [len(adj[i]) for i in range(n)]
    print(f"\nDegrees: {degrees}")
    print(f"Min degree: {min(degrees)} (need >= 3)")
    print(f"Max degree: {max(degrees)} (need <= 4)")
    print(f"Number of edges: {len(edges)} (need 13-16)")

    # Check fixed edges
    print(f"\nFixed edge (0,7) present: {(0,7) in edges or (7,0) in edges}")
    print(f"Fixed edge (1,7) present: {(1,7) in edges or (7,1) in edges}")

    # Check chromatic number
    def chromatic_number(adj, n):
        for k in range(1, n+1):
            if is_k_colorable(adj, n, k):
                return k
        return n

    def is_k_colorable(adj, n, k):
        colors = [-1] * n
        def backtrack(v):
            if v == n:
                return True
            for c in range(k):
                valid = True
                for neighbor in adj[v]:
                    if neighbor < v and colors[neighbor] == c:
                        valid = False
                        break
                if valid:
                    colors[v] = c
                    if backtrack(v + 1):
                        return True
                    colors[v] = -1
            return False
        return backtrack(0)

    chi = chromatic_number(adj, n)
    print(f"Chromatic number: {chi} (need 2 <= chi <= 3)")

    # Show a valid coloring
    colors = [-1] * n
    def find_coloring(v, k):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in adj[v]:
                if neighbor < v and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if find_coloring(v + 1, k):
                    return True
                colors[v] = -1
        return False

    find_coloring(0, chi)
    print(f"Coloring: {colors}")

    # Verify all constraints
    all_ok = True
    if min(degrees) < 3:
        print("FAIL: min degree < 3")
        all_ok = False
    if max(degrees) > 4:
        print("FAIL: max degree > 4")
        all_ok = False
    if len(edges) < 13 or len(edges) > 16:
        print("FAIL: edges not in [13,16]")
        all_ok = False
    if chi < 2 or chi > 3:
        print("FAIL: chromatic number not in [2,3]")
        all_ok = False
    if (0,7) not in edges and (7,0) not in edges:
        print("FAIL: (0,7) not present")
        all_ok = False
    if (1,7) not in edges and (7,1) not in edges:
        print("FAIL: (1,7) not present")
        all_ok = False

    if all_ok:
        print("\nALL CONSTRAINTS SATISFIED!")

    return all_ok

